/* Card portraits retain their source proportions and transparent edges. */
.card-art{display:block;position:absolute;inset:0;width:100%;height:100%;object-fit:contain;object-position:center;border-radius:6px;pointer-events:none;user-select:none;-webkit-user-select:none;-webkit-user-drag:none}
.card .card-art{z-index:0}
.card .form-mark{z-index:4}
.detail-hero{height:202px;max-width:168px}
.detail-hero .card-art{border-radius:8px}
.ability-portrait{inset:0 0 14px;overflow:hidden;border-radius:9px 9px 0 0}
.ability-portrait .card-art{object-fit:cover;object-position:50% 28%;border-radius:0}

/* Clock warnings have their own channel so phase and crown messages remain visible. */
.time-alert{position:absolute;left:50%;top:23%;z-index:8;width:max-content;max-width:95%;transform:translate(-50%,-50%);text-align:center;pointer-events:none;opacity:0;line-height:1.05}
.time-alert strong{display:block;font:900 clamp(26px,6vw,38px)/1.1 var(--heading);color:#ffe6a6;letter-spacing:.6px;text-shadow:0 3px #725125,2px 0 #4b341f,-2px 0 #4b341f,0 -2px #4b341f,0 5px 14px #142635}
.time-alert>span{display:block;margin-top:7px;font:800 12px/1 var(--heading);letter-spacing:2px;color:#fff2cf;text-shadow:0 2px 4px #12253d}
.time-alert.visible{opacity:1;animation:time-alert-enter .25s ease-out}
.time-alert.final-countdown{top:51%;width:150px}
.final-countdown strong{font-size:clamp(74px,20vw,114px);color:#fff0bb;text-shadow:0 5px #bd762e,3px 0 #674124,-3px 0 #674124,0 -3px #674124,0 8px 20px #17304699}
.final-countdown.urgent strong{color:#ffb5a4;text-shadow:0 5px #a53435,3px 0 #632732,-3px 0 #632732,0 -3px #632732,0 8px 20px #17304699}
.final-countdown.visible{animation:time-number .9s ease-out both}
.canvas-wrap.counting-down .arena-banner{top:26%}
@keyframes time-alert-enter{from{opacity:0;transform:translate(-50%,-50%) scale(.88)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}
@keyframes time-number{0%{opacity:0;transform:translate(-50%,-50%) scale(1.25)}14%,72%{opacity:1;transform:translate(-50%,-50%) scale(1)}100%{opacity:0;transform:translate(-50%,-50%) scale(.92)}}
body.effects-off .time-alert.visible{animation:none}
@media(prefers-reduced-motion:reduce){.time-alert.visible{animation:none}}

/* Battle-first layout: names and timer sit inside the arena; cards stay close to the thumb. */
.game-column{grid-template-rows:minmax(0,1fr) clamp(150px,18dvh,177px)}
.battle-hud{position:absolute;top:5px;left:9px;right:9px;height:42px;padding:0;background:none;border:0;pointer-events:none;z-index:5}
.battle-hud .avatar{display:none}
.opponent-identity{max-width:44%;align-self:flex-start;padding-top:4px}
.opponent-identity strong{font-size:21px;color:#fff1dd;text-shadow:0 2px 2px #352619,1px 0 #352619,-1px 0 #352619}
.opponent-identity small{font-size:10px;color:#f2d2c5;text-shadow:0 1px 2px #3c2429}
.match-clock{left:auto;right:78px;transform:none;align-items:flex-end;min-width:60px}
.battle-timer{font-size:30px;text-shadow:0 2px 2px #261e1c,1px 0 #261e1c,-1px 0 #261e1c}
#phase-label{font-size:10px;color:#fff2d3;text-shadow:0 1px 2px #342623}
.hud-buttons{margin:0;gap:5px;pointer-events:auto;align-self:flex-start;padding-top:2px}
.hud-buttons .iconbutton{background:#384849a8;border:1px solid #e4dfc77a;width:32px;height:32px}
.canvas-wrap{border:0}
.crown-score{left:auto;top:auto;right:5px;bottom:45%;flex-direction:column;gap:7px;background:#293630b8;border:1px solid #fff1cb45;padding:5px 3px;border-radius:6px;box-shadow:none}
.crown-score i{height:1px;width:25px}
.crown-score>span{font-size:18px;text-shadow:0 1px 2px #203229}
.crown-score svg{width:17px;height:17px}
.phase{top:53px;right:8px;font-size:13px;background:#392849af}
.battle-dock{background:linear-gradient(180deg,#666a70,#424951 20%,#303844);border-top:4px solid #bab5a0;box-shadow:inset 0 2px #34312b,0 -3px 9px #1b241f70;padding:4px 11px 8px;grid-template-rows:18px minmax(0,1fr) 26px}
.battle-hint{color:#f2dfb5}
.hand-tray{gap:13px;padding-top:5px}
.hand .card{border-color:#c5c8c3;border-bottom-color:#676d70;box-shadow:0 3px 4px #0b1729aa;transition:transform .12s,border-color .12s,filter .12s}
.hand .card.selected{transform:translateY(-11px) scale(1.04);border-color:#fff4bd;box-shadow:0 0 0 2px #fff5c977,0 5px 8px #0b1729aa;z-index:3}
.hand .card-name{opacity:0;font-size:14px;transition:opacity .12s;z-index:4;pointer-events:none}
.hand .card.selected .card-name{opacity:1}
.hand .card.unaffordable{filter:saturate(.35) brightness(.8)}
.card-charge{position:absolute;inset:0;background:#131b2b65;clip-path:inset(0 0 calc(var(--card-fill,1)*100%) 0);pointer-events:none;z-index:1;border-radius:5px}
.hand .card.dealt-in{animation:card-dealt .24s ease-out}
@keyframes card-dealt{from{transform:translate(-12px,20px) scale(.65);opacity:.2}to{transform:translate(0,0) scale(1);opacity:1}}
.next-card>span{color:#e9e1c9;font-size:11px}
.next-card .card-name{display:none}
.elixir-track{height:18px;border:2px solid #d6bddb;border-radius:5px;background:#4f2759}
.elixir-track>div{background:linear-gradient(180deg,#f6b9ff 0,#dc78ef 40%,#b847cf 44%,#d16aea);transition:width .1s linear}
.elixir-track i{background:#532563cc;border-left:1px solid #edb5f74d}
body.effects-off .hand .card.dealt-in{animation:none}
@media(max-width:600px){.game-column{grid-template-rows:minmax(0,1fr) 150px}.battle-dock{padding:4px 10px 8px}.hand{gap:9px}.hand .card-name{font-size:14px}.match-clock{right:74px}.opponent-identity strong{font-size:20px}}
@media(max-width:380px){.game-column{grid-template-rows:minmax(0,1fr) 143px}.hand{gap:8px}.hand-tray{gap:12px}.opponent-identity strong{font-size:18px}.battle-timer{font-size:28px}}
