:root{--heading:'Royale','Barlow Condensed','Arial Black',sans-serif;--body:'Barlow',system-ui,sans-serif;--royale-shadow:0 2px 0 #0b1421,1px 0 0 #0b1421,-1px 0 0 #0b1421,0 -1px 0 #0b1421}
