.resource{position:relative;min-width:0;height:29px;border:2px solid #477c94;border-radius:6px;background:linear-gradient(#07101e,#172d40);box-shadow:0 2px #060d19,inset 0 2px #06111d;padding:0 13px 0 19px;display:flex;justify-content:flex-end;align-items:center;font:18px var(--heading);text-shadow:var(--royale-shadow)}
