","interface.css":"/* Shared phone geometry. Deck interactions never resize or replace this shell. */
.game-shell.royale-shell{--resources-height:50px;--nav-height:70px;width:min(100%,480px);min-height:0;grid-template-columns:minmax(0,1fr);grid-template-rows:50px minmax(0,1fr) calc(70px + env(safe-area-inset-bottom));padding-top:env(safe-area-inset-top);border:0}
.game-shell .royale-main{grid-column:1;grid-row:2;min-width:0;min-height:0;overflow-x:hidden;scroll-behavior:auto}
