.game-shell .royale-tab>.royale-art{height:43px;width:46px;transform:none}
.game-shell .royale-tab.active>.royale-art{height:49px;width:54px;transform:translateY(-2px)}
.game-shell .royale-tab>span{font-size:12px;line-height:17px;height:17px;transform:none}
.game-shell .royale-tab.active>span{transform:none;opacity:1}
.game-shell button{font-synthesis:none}
.cr-resources{grid-row:1;grid-column:1;display:grid;grid-template-columns:1fr 1fr .85fr;gap:12px;align-items:center;padding:5px 11px 5px 14px;position:relative;z-index:10;background:linear-gradient(#0b1525ed,#13263b);border-bottom:2px solid #6facc155}
