.cr-header{display:grid;grid-template-columns:minmax(0,1.52fr) minmax(0,1fr);grid-template-rows:40px minmax(56px,1fr);gap:8px;padding:13px 10px 6px;background:linear-gradient(#151221,#16283c77 60%,transparent);min-width:0;position:relative;z-index:3}
