.cr-shortcut{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;background:none;padding:0;width:58px;min-height:64px;position:relative}
.cr-shortcut>img{height:49px;width:53px;object-fit:contain;filter:drop-shadow(0 3px 2px #1034499e)}
.cr-shortcut>span{font:11px/15px var(--heading);text-shadow:var(--royale-shadow);white-space:nowrap}
