  if (item.kind === 'frame') return lobbyView.bannerPreview(defaultPreview, 'archers', item.id);
  if (item.kind === 'emote') return emotes.imageHTML(item.id);
  if (item.kind === 'badge') return cosmetics.badgeHTML(item.id);
