}
function itemLabel(item) {
  return Object.hasOwn(names, item.kind) ? `+${format(item.amount)} ${unitName(item.kind, item.amount)}` : `${item.name} · ${kinds[item.kind]}`;
}
function summaryText(items) {
  return cleanItems(items).map(itemLabel).join('; ');
