exports.summaryText = summaryText;

function revealHTML({ title = 'Rewards collected', items = [], effects = true, compact = false } = {}) {
  const gains = cleanItems(items);
  if (!gains.length) return '';
  return `<section class="cf-reward-reveal${effects === false ? ' effects-off' : ''}${compact ? ' cf-reveal-compact' : ''}" aria-label="${esc(title)}"><header class="cf-reveal-heading"><span class="cf-reveal-kicker">Added to your collection</span><h2>${esc(title)}</h2><p>${gains.length === 1 ? '1 reward received' : `${gains.length} rewards received`}</p></header><ul class="cf-reveal-items" aria-label="Everything received">${gains.map((item, index) => `<li class="cf-reveal-item cf-reveal-${item.kind}" style="--reveal-delay:${Math.min(index, 8) * 45}ms" data-reward-kind="${item.kind}" data-reward-id="${esc(item.id)}"><span class="cf-reveal-art" aria-hidden="true">${itemArt(item)}</span><span class="cf-reveal-copy"><strong>${esc(Object.hasOwn(names, item.kind) ? `+${format(item.amount)}` : item.name)}</strong><span>${esc(Object.hasOwn(names, item.kind) ? unitName(item.kind, item.amount) : `New ${kinds[item.kind].toLowerCase()}`)}</span></span></li>`).join('')}</ul>${compact ? '' : '<footer class="cf-reveal-footer"><p>Saved. Your rewards are ready to use.</p><button type="button" class="primary full-button" data-reward-continue autofocus>Continue</button></footer>'}</section>`;
}
exports.revealHTML = revealHTML;

// Call only after a successful save, with the exact before/after transaction snapshots.
// onContinue runs once for Continue, Escape, the close button or backdrop dismissal.
function showReveal(modal, beforeProfile, afterProfile, title = 'Rewards collected', options = {}) {
  const items = rewardDiff(beforeProfile, afterProfile);
  if (!items.length || typeof modal !== 'function') return null;
