"use strict";

const CSS = `.updates-modal .updates-panel h2{padding-right:44px}.updates-modal .updates-version{display:grid;gap:5px;padding:14px;border:1px solid #668ba9;border-radius:10px;background:#112d46}.updates-modal .updates-version small{font-size:11px;letter-spacing:.08em;color:#accbe1}.updates-modal .updates-version strong{font-size:19px;color:#fff4c7}.updates-modal .updates-panel .full-button{display:block;width:100%;min-height:44px;margin:10px 0 0}.updates-modal .updates-panel details{margin-top:16px}.updates-modal .updates-panel summary{min-height:44px;cursor:pointer;line-height:1.4}.updates-modal .updates-panel .updates-source{font-size:12px;overflow-wrap:anywhere;color:#accbe1}.updates-modal .updates-panel [hidden]{display:none!important}`;
