  const status = d.querySelector('[data-update-status]');
  function paint(state) {
    d.querySelector('[data-update-version]').textContent = state.label || 'Bundled version';
    status.textContent = state.message || 'Ready to play.';
    const enabled = d.querySelector('[data-update-enabled]');
    enabled.checked = state.enabled;
    d.querySelector('[data-update-check]').disabled = state.checkInProgress || state.phase === 'loading' || !state.source;
