    d.querySelector('[data-update-match-note]').hidden = canRestart();
    d.querySelector('[data-update-bundled]').disabled = !canRestart();
    d.querySelector('[data-update-source]').textContent = state.source ? `Update source: ${state.source}` : 'No update source is connected yet.';
  }
