  d.querySelector('[data-update-restart]').onclick = () => {
    if (canRestart()) updater.restart();
  };
  d.querySelector('[data-update-bundled]').onclick = () => {
    if (canRestart()) updater.restart({ bundled: true });
  };
  return d;
}
