/* CROWNFALL MOBILE UI START */
/* Mobile review: bounded dialog contents and touch targets in the lobby.
   Scoped away from battle emote geometry and the friendly arena. */
dialog.modal:not(.friend-arena-modal){box-sizing:border-box;max-height:calc(var(--app-height,100dvh) - 24px);overscroll-behavior:contain;overflow-wrap:anywhere}
dialog.modal:not(.friend-arena-modal):not(.card-profile-modal):not(.reward-reveal-modal):not(.banner-editor-modal){scroll-padding-block:58px 16px}
dialog.modal:not(.friend-arena-modal):not(.card-profile-modal):not(.reward-reveal-modal):not(.banner-editor-modal)>.modal-close{position:sticky;top:0;right:auto;float:right;width:44px;height:44px;min-width:44px;min-height:44px;margin:-12px -8px 8px 12px;z-index:10}
dialog.modal:not(.friend-arena-modal) .setting-row{gap:12px;min-height:54px}
dialog.modal:not(.friend-arena-modal) .setting-row input[type="checkbox"]{flex:none}
dialog.modal:not(.friend-arena-modal) .setting-row select{min-width:0;max-width:58%;min-height:44px}
dialog.modal .profile-name{align-items:stretch}
dialog.modal .profile-name button{margin-top:0;min-height:44px}
dialog.modal .profile-name input{min-width:0;min-height:44px}
dialog.modal .menu-list button{white-space:normal;overflow-wrap:anywhere}
dialog.modal:not(.friend-arena-modal) .full-button+ .full-button{margin-left:0}
dialog.modal:not(.friend-arena-modal) .backup-preview dl{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
dialog.modal:not(.friend-arena-modal) .backup-preview dd{min-width:0;overflow-wrap:anywhere}
.card-profile-modal .cp-level{min-width:0;overflow-wrap:anywhere}
.card-profile-modal .cp-heading{min-height:52px;padding-right:64px}
.card-profile-modal .cp-done{min-height:44px}
.card-profile-modal .modal-close{width:44px;height:44px;min-width:44px;min-height:44px}
.card-profile-modal .cp-sheet-label{min-width:0;white-space:normal}
.game-shell .royale-tab>span{opacity:1}

@media(max-width:600px){
  dialog.modal:not(.friend-arena-modal) input:not([type="checkbox"]):not([type="range"]):not([type="file"]),dialog.modal:not(.friend-arena-modal) select{font-size:16px}
  dialog.modal:not(.friend-arena-modal) .textbutton,dialog.modal:not(.friend-arena-modal) summary{min-height:44px}
  dialog.modal:not(.friend-arena-modal) .textbutton{max-width:100%;white-space:normal}
  .game-shell .editor-tabs>button{min-height:44px}
  .game-shell .editor-toolbar{grid-template-columns:repeat(3,44px);justify-content:space-between;gap:7px;height:auto;padding:8px}
  .game-shell .editor-deck-numbers{grid-column:1/-1;grid-row:1;grid-template-columns:repeat(5,minmax(44px,1fr));gap:7px}
  .game-shell .editor-deck-numbers>button{height:44px;min-height:44px}
  .game-shell .editor-deck-numbers>button.active:before{inset:-3px -3px -6px}
  .game-shell .editor-toolbar>.deck-tool{grid-row:2;width:44px;height:44px;min-height:44px}
  .game-shell .editor-toolbar>[data-editor-menu]{grid-column:1}
  .game-shell .editor-toolbar>[data-editor-reorder]{grid-column:2}
  .game-shell .editor-toolbar>[data-editor-copy]{grid-column:3}
  .game-shell .editor-collection-bar{grid-template-columns:minmax(0,1fr) 44px 44px 80px;gap:5px;padding:6px}
  .game-shell .editor-collection-bar h2{font-size:15px;line-height:1.25}
