  .game-shell .editor-collection-bar .deck-tool,.game-shell .editor-sort{height:44px;min-height:44px}
  .game-shell .editor-card-actions .editor-blue,.game-shell .editor-card-actions .editor-red{min-height:44px}
  .game-shell .editor-deck-summary>.deck-tool{width:44px;height:44px;min-height:44px}
  .game-shell .editor-deck-summary .deck-status{min-width:0;overflow-wrap:anywhere}
  .game-shell .editor-collection-grid{scroll-margin-top:176px}
  .cf-shop .cf-section-heading{flex-wrap:wrap}
  .cf-shop .cf-section-heading h2{min-width:0;overflow-wrap:anywhere}
  .cf-shop .cf-section-heading>span{margin-left:auto}
  .cf-shop .cf-feature-info{flex-wrap:wrap}
  .cf-shop .cf-feature-info>div{flex:1 1 130px;min-width:0}
  .cf-shop .cf-feature-info>.cf-shop-buy{margin-left:auto}
  .cf-shop .cf-key-explainer{flex-wrap:wrap}
  .cf-shop .cf-key-explainer p{min-width:120px}
  .cf-shop .cf-key-explainer>.cf-shop-link{margin-left:auto}
  .collection-book .book-set-heading{flex-wrap:wrap}
  .collection-book .book-set-status{margin-left:auto}
}

@media(max-width:374px){
  dialog.modal:not(.friend-arena-modal):not(.card-profile-modal):not(.reward-reveal-modal):not(.banner-editor-modal){padding-inline:14px}
  dialog.modal:not(.friend-arena-modal) .setting-row{font-size:14px}
  .game-shell .editor-collection-bar{grid-template-columns:minmax(0,1fr) 44px 44px 70px;gap:4px;padding:4px}
  .game-shell .editor-collection-bar h2{font-size:13px}
  .game-shell .editor-collection-bar p{font-size:11px}
  .game-shell .editor-sort{font-size:12px}
  .card-profile-modal .cp-sheet-label{font-size:17px}
  .card-profile-modal .cp-heading{gap:6px}
  .card-profile-modal .cp-level{flex:0 1 84px}
  .game-shell .royale-tab>span{font-size:11px}
}

/* Short landscape and the on-screen keyboard must not trap content under fixed headers. */
@media(max-height:450px){
  .game-shell .editor-tabs,.game-shell .editor-toolbar{position:relative;top:auto}
  .game-shell .editor-footer>.editor-blue{min-height:44px;height:44px}
  .game-shell.deck-shell{grid-template-rows:44px minmax(0,1fr) calc(61px + env(safe-area-inset-bottom))}
  dialog.modal.card-profile-modal .card-profile{display:block;overflow-y:auto;overscroll-behavior:contain;max-height:calc(var(--app-height,100dvh) - 36px)}
  dialog.modal.card-profile-modal .cp-heading{position:sticky;top:0;z-index:4;min-height:50px;padding-right:64px}
  dialog.modal.card-profile-modal .cp-body{overflow:visible}
  dialog.modal.card-profile-modal .cp-footer{position:sticky;bottom:0;z-index:3}
  dialog.modal.card-profile-modal .modal-close{top:4px;right:5px;width:44px;height:44px;min-width:44px;min-height:44px}
  .battle-screen .pause-panel{max-height:calc(var(--app-height,100dvh) - 20px);overflow-y:auto;overscroll-behavior:contain}
}

@media(prefers-reduced-motion:reduce){dialog.modal{scroll-behavior:auto}}

/* The new profile and rematch forms also need readable phone-sized controls. */
@media(max-width:600px){.cosmetic-page .cosmetic-selectors select,.friend-arena-modal .cf-friendly-panel .cf-friendly-rematch-deck select{font-size:16px}.cosmetic-page .cosmetic-progress-label b{min-width:0;overflow-wrap:anywhere}.cosmetic-page .cosmetic-item-heading{flex-wrap:wrap}.cosmetic-page .cosmetic-item-heading h2{min-width:0;overflow-wrap:anywhere}}

